Action.Str:
/* Materialize Run inputs as real Tasker locals for native actions. */
task_name_value = tasker.getVariable("task_name");
arg1_value = tasker.getVariable("arg1");
arg2_value = tasker.getVariable("arg2");
command_id_value = tasker.getVariable("command_id");
result_token_value = tasker.getVariable("result_token");
priority_text = tasker.getVariable("priority");

if (task_name_value == null) task_name_value = "";
if (command_id_value == null) command_id_value = "";
if (result_token_value == null) result_token_value = "";
if (priority_text == null) priority_text = "";

/* Accept both the current arg1/arg2 contract and legacy par1/par2 names. */
if (arg1_value == null || arg1_value.length() == 0) {
    arg1_value = tasker.getVariable("par1");
}
if (arg2_value == null || arg2_value.length() == 0) {
    arg2_value = tasker.getVariable("par2");
}
if (arg1_value == null) arg1_value = "";
if (arg2_value == null) arg2_value = "";

run_priority_value = 7;
run_error_value = "";

if (task_name_value.length() == 0) {
    run_error_value = "missing_task_name";
} else if (task_name_value.indexOf("Hermes · Capability · ") != 0) {
    run_error_value = "task_not_allowed";
}

if (run_error_value.length() == 0 && priority_text.length() > 0) {
    try {
        run_priority_value = java.lang.Integer.parseInt(priority_text);
        if (!java.lang.String.valueOf(run_priority_value).equals(priority_text)) {
            run_error_value = "invalid_priority";
        } else if (run_priority_value < 0 || run_priority_value > 50) {
            run_error_value = "invalid_priority";
        }
    } catch (java.lang.NumberFormatException priority_error) {
        run_error_value = "invalid_priority";
    }
}

tasker.setVariable("run_task_name", task_name_value);
tasker.setVariable("run_par1", arg1_value);
tasker.setVariable("run_par2", arg2_value);
tasker.setVariable("run_command_id", command_id_value);
tasker.setVariable("run_result_token", result_token_value);
tasker.setVariable("run_priority", java.lang.String.valueOf(run_priority_value));
tasker.setVariable("run_error", run_error_value);
tasker.setVariable("run_child_result", "");

tasker.log(
    "Hermes run init task=" + task_name_value
    + ";arg1_len=" + arg1_value.length()
    + ";arg2_len=" + arg2_value.length()
    + ";priority=" + run_priority_value
    + ";error=" + run_error_value
);

return run_error_value;

/* Run Perform Task failed - reads Intent extras + native outputs. */
command_id = tasker.getVariable("command_id");
task_name = tasker.getVariable("task_name");
result_token = tasker.getVariable("result_token");
if (command_id == null) command_id = "";
if (task_name == null) task_name = "";
if (result_token == null) result_token = "";
now = java.lang.System.currentTimeMillis();

result = new org.json.JSONObject();
result.put("ok", false);
result.put("command_id", command_id);
result.put("task_name", task_name);
result.put("error_code", "perform_task_failed");
result.put("tasker_error", tasker.getVariable("err") != null ? tasker.getVariable("err") : "");
result.put("error_message", tasker.getVariable("errmsg") != null ? tasker.getVariable("errmsg") : "");
result.put("finished_at_ms", now);
result_json = result.toString();

envelope = new org.json.JSONObject();
envelope.put("schema", "hermes-tasker-result/v1");
envelope.put("operation", "run");
envelope.put("command_id", command_id);
envelope.put("result_token", result_token);
envelope.put("result_json", result_json);
envelope.put("finished_at_ms", now);
envelope_json = envelope.toString();
/* Submit via ContentProvider */
provider_output = "";
try {
    extras = new android.os.Bundle();
    extras.putString("result_json", envelope_json);
    reply = context.getContentResolver().call(
        android.net.Uri.parse("content://com.hermesandroid.bridge.taskerresult"),
        "submit_result", null, extras);
    if (reply == null) {
        provider_output = "accepted=false;reason=null_reply";
    } else {
        accepted = reply.getBoolean("accepted", false);
        reason = reply.getString("reason");
        if (reason == null) reason = "";
        provider_output = "accepted=" + accepted + ";reason=" + reason;
    }
} catch (java.lang.Throwable e) {
    provider_output = "accepted=false;reason=exception:" + e.getClass().getName() + ":" + String.valueOf(e.getMessage());
}
tasker.setVariable("run_result_json", result_json, true);
tasker.setVariable("HermesLastRun", result_json, true);
tasker.setVariable("provider_reply", provider_output);
tasker.setVariable("HermesLastProviderReply", provider_output);
tasker.log("Hermes provider " + provider_output);
return provider_output;

/* Run success / missing_return - reads Intent extras + native run_child_result. */
command_id = tasker.getVariable("command_id");
task_name = tasker.getVariable("task_name");
result_token = tasker.getVariable("result_token");
child_result = tasker.getVariable("run_child_result");
if (command_id == null) command_id = "";
if (task_name == null) task_name = "";
if (result_token == null) result_token = "";
if (child_result == null) child_result = "";
now = java.lang.System.currentTimeMillis();

result = new org.json.JSONObject();
result.put("command_id", command_id);
result.put("task_name", task_name);
result.put("finished_at_ms", now);
if (child_result.length() == 0) {
    result.put("ok", false);
    result.put("error_code", "missing_return");
    result.put("error_message", "Capability returned no value");
} else {
    result.put("ok", true);
    result.put("result", child_result);
}
result_json = result.toString();

envelope = new org.json.JSONObject();
envelope.put("schema", "hermes-tasker-result/v1");
envelope.put("operation", "run");
envelope.put("command_id", command_id);
envelope.put("result_token", result_token);
envelope.put("result_json", result_json);
envelope.put("finished_at_ms", now);
envelope_json = envelope.toString();
/* Submit via ContentProvider */
provider_output = "";
try {
    extras = new android.os.Bundle();
    extras.putString("result_json", envelope_json);
    reply = context.getContentResolver().call(
        android.net.Uri.parse("content://com.hermesandroid.bridge.taskerresult"),
        "submit_result", null, extras);
    if (reply == null) {
        provider_output = "accepted=false;reason=null_reply";
    } else {
        accepted = reply.getBoolean("accepted", false);
        reason = reply.getString("reason");
        if (reason == null) reason = "";
        provider_output = "accepted=" + accepted + ";reason=" + reason;
    }
} catch (java.lang.Throwable e) {
    provider_output = "accepted=false;reason=exception:" + e.getClass().getName() + ":" + String.valueOf(e.getMessage());
}
tasker.setVariable("run_result_json", result_json, true);
tasker.setVariable("HermesLastRun", result_json, true);
tasker.setVariable("provider_reply", provider_output);
tasker.setVariable("HermesLastProviderReply", provider_output);
tasker.log("Hermes provider " + provider_output);
return provider_output;

/* Run validation error - reads Intent extras directly. */
command_id = tasker.getVariable("command_id");
task_name = tasker.getVariable("task_name");
priority_raw = tasker.getVariable("priority");
if (command_id == null) command_id = "";
if (task_name == null) task_name = "";
if (priority_raw == null) priority_raw = "";
now = java.lang.System.currentTimeMillis();

/* Replicate validation */
error_code = "";
if (task_name.length() == 0) error_code = "missing_task_name";
else if (task_name.indexOf("Hermes · Capability · ") != 0) error_code = "task_not_allowed";
if (error_code.length() == 0 && priority_raw.length() > 0) {
    try {
        priority_val = java.lang.Integer.parseInt(priority_raw);
        if (!java.lang.String.valueOf(priority_val).equals(priority_raw)) {
            error_code = "invalid_priority";
        } else if (priority_val < 0 || priority_val > 50) {
            error_code = "invalid_priority";
        }
    } catch (java.lang.NumberFormatException priority_error) {
        error_code = "invalid_priority";
    }
}

result = new org.json.JSONObject();
result.put("ok", false);
result.put("command_id", command_id);
result.put("task_name", task_name);
result.put("error_code", error_code);
result.put("error_message", error_code);
result.put("finished_at_ms", now);
result_json = result.toString();

envelope = new org.json.JSONObject();
envelope.put("schema", "hermes-tasker-result/v1");
envelope.put("operation", "run");
envelope.put("command_id", command_id);
envelope.put("result_token", tasker.getVariable("result_token") != null ? tasker.getVariable("result_token") : "");
envelope.put("result_json", result_json);
envelope.put("finished_at_ms", now);
envelope_json = envelope.toString();
/* Submit via ContentProvider */
provider_output = "";
try {
    extras = new android.os.Bundle();
    extras.putString("result_json", envelope_json);
    reply = context.getContentResolver().call(
        android.net.Uri.parse("content://com.hermesandroid.bridge.taskerresult"),
        "submit_result", null, extras);
    if (reply == null) {
        provider_output = "accepted=false;reason=null_reply";
    } else {
        accepted = reply.getBoolean("accepted", false);
        reason = reply.getString("reason");
        if (reason == null) reason = "";
        provider_output = "accepted=" + accepted + ";reason=" + reason;
    }
} catch (java.lang.Throwable e) {
    provider_output = "accepted=false;reason=exception:" + e.getClass().getName() + ":" + String.valueOf(e.getMessage());
}
tasker.setVariable("run_result_json", result_json, true);
tasker.setVariable("HermesLastRun", result_json, true);
tasker.setVariable("provider_reply", provider_output);
tasker.setVariable("HermesLastProviderReply", provider_output);
tasker.log("Hermes provider " + provider_output);
return provider_output;

/* Build a real structured return value without JavaScriptlet handoff. */
input1 = tasker.getVariable("par1");
input2 = tasker.getVariable("par2");

if (input1 == null) input1 = "";
if (input2 == null) input2 = "";

result = new org.json.JSONObject();
result.put("ok", true);
result.put("capability", "smoke.v1");
result.put("par1", input1);
result.put("par2", input2);
result.put(
    "timestamp_ms",
    java.lang.System.currentTimeMillis()
);

result_json = result.toString();

tasker.setVariable(
    "result_json",
    result_json,
    true
);

return result_json;

/* Build probe result JSON, envelope, and submit via ContentProvider. */
command_id = tasker.getVariable("command_id");
result_token = tasker.getVariable("result_token");
probe_token = tasker.getVariable("probe_token");
if (command_id == null) command_id = "";
if (result_token == null) result_token = "";
if (probe_token == null) probe_token = "";
now = java.lang.System.currentTimeMillis();

// Build result JSON
result = new org.json.JSONObject();
result.put("ok", true);
result.put("command_id", command_id);
result.put("probe_token", probe_token);
result.put("schema", "hermes-tasker-probe-result/v1");
result.put("finished_at_ms", now);
result_json = result.toString();

// Build envelope JSON
envelope = new org.json.JSONObject();
envelope.put("schema", "hermes-tasker-result/v1");
envelope.put("operation", "probe");
envelope.put("command_id", command_id);
envelope.put("result_token", result_token);
envelope.put("result_json", result_json);
envelope.put("finished_at_ms", now);
envelope_json = envelope.toString();

// Submit via ContentProvider
provider_output = "";
try {
    extras = new android.os.Bundle();
    extras.putString("result_json", envelope_json);

    reply = context.getContentResolver().call(
        android.net.Uri.parse("content://com.hermesandroid.bridge.taskerresult"),
        "submit_result",
        null,
        extras
    );

    if (reply == null) {
        provider_output = "accepted=false;reason=null_reply";
    } else {
        accepted = reply.getBoolean("accepted", false);
        reason = reply.getString("reason");
        if (reason == null) reason = "";
        provider_output = "accepted=" + accepted + ";reason=" + reason;
    }
} catch (java.lang.Throwable e) {
    provider_output = "accepted=false;reason=exception:" + e.getClass().getName() + ":" + String.valueOf(e.getMessage());
}

// Store results for Notify
tasker.setVariable("probe_result_json", result_json, true);
tasker.setVariable("HermesLastProbe", result_json, true);
tasker.setVariable("provider_reply", provider_output);
tasker.setVariable("HermesLastProviderReply", provider_output);
tasker.log("Hermes provider " + provider_output);
return provider_output;

/*
 * NATIVE_ACTION_NOT_USED:
 * Tasker has no native action that hashes exact UTF-8 bytes and classifies a
 * Tasker export without mutating it. This is intentionally a narrow scanner,
 * not a DOM parser. Deep graph validation remains the host's responsibility.
 *
 * INPUTS: data, command_id, result_token
 * OUTPUTS: import_xml, import_error, import_artifact_type, import_name,
 *          import_sha256, import_verify_type, import_command_id,
 *          import_result_token
 */
command_id = tasker.getVariable("command_id");
result_token = tasker.getVariable("result_token");
data_xml = tasker.getVariable("data");
if (command_id == null) command_id = "";
if (result_token == null) result_token = "";
if (data_xml == null) data_xml = "";

import_error = "";
artifact_type = "";
artifact_name = "";
sha256_val = "";
verify_type = "";

if (data_xml.length() > 0) {
    try {
        digest_bytes = java.security.MessageDigest.getInstance("SHA-256").digest(data_xml.getBytes("UTF-8"));
        hex_buf = "";
        for (digest_index = 0; digest_index < digest_bytes.length; digest_index++) {
            hex_part = java.lang.Integer.toHexString(digest_bytes[digest_index] & 255);
            if (hex_part.length() < 2) hex_buf += "0";
            hex_buf += hex_part;
        }
        sha256_val = hex_buf;
    } catch (java.lang.Throwable hash_error) {
        import_error = "sha256_failed";
    }
}

if (import_error.length() == 0 && data_xml.length() == 0) import_error = "missing_data";
if (import_error.length() == 0 && data_xml.getBytes("UTF-8").length > 65536) import_error = "payload_too_large";
if (import_error.length() == 0 && data_xml.indexOf("eval(") >= 0) import_error = "eval_policy";
if (import_error.length() == 0 && (data_xml.indexOf("<!DOCTYPE") >= 0 || data_xml.indexOf("<!ENTITY") >= 0)) import_error = "doctype_not_allowed";

scan_xml = data_xml.trim();
if (import_error.length() == 0 && (scan_xml.indexOf("<TaskerData") < 0 || scan_xml.lastIndexOf("</TaskerData>") < 0)) import_error = "invalid_root";

project_count = 0;
profile_count = 0;
task_count = 0;
if (import_error.length() == 0) {
    scan_pos = 0;
    while ((scan_pos = scan_xml.indexOf("<Project ", scan_pos)) >= 0) { project_count++; scan_pos += 9; }
    scan_pos = 0;
    while ((scan_pos = scan_xml.indexOf("<Profile ", scan_pos)) >= 0) { profile_count++; scan_pos += 9; }
    scan_pos = 0;
    while ((scan_pos = scan_xml.indexOf("<Task ", scan_pos)) >= 0) { task_count++; scan_pos += 6; }

    primary_start = -1;
    primary_end = -1;
    name_open = "";
    name_close = "";

    if (project_count == 1) {
        artifact_type = "project";
        verify_type = "11";
        primary_start = scan_xml.indexOf("<Project ");
        primary_end = scan_xml.indexOf("</Project>", primary_start);
        name_open = "<name>";
        name_close = "</name>";
    } else if (project_count == 0 && profile_count == 1 && task_count >= 1) {
        artifact_type = "profile";
        verify_type = "5";
        primary_start = scan_xml.indexOf("<Profile ");
        primary_end = scan_xml.indexOf("</Profile>", primary_start);
        name_open = "<nme>";
        name_close = "</nme>";
    } else if (project_count == 0 && profile_count == 0 && task_count == 1) {
        artifact_type = "task";
        verify_type = "7";
        primary_start = scan_xml.indexOf("<Task ");
        primary_end = scan_xml.indexOf("</Task>", primary_start);
        name_open = "<nme>";
        name_close = "</nme>";
    } else {
        import_error = "invalid_artifact_layout";
    }

    if (import_error.length() == 0 && (primary_start < 0 || primary_end < 0)) import_error = "invalid_artifact_layout";
    if (import_error.length() == 0) {
        name_start = scan_xml.indexOf(name_open, primary_start);
        name_end = name_start >= 0 ? scan_xml.indexOf(name_close, name_start + name_open.length()) : -1;
        if (name_start < 0 || name_end < 0 || name_end > primary_end) import_error = "missing_name";
        else artifact_name = scan_xml.substring(name_start + name_open.length(), name_end);
    }

    if (artifact_name != null) {
        artifact_name = artifact_name.replace("&lt;", "<").replace("&gt;", ">").replace("&quot;", "\"").replace("&apos;", "'").replace("&amp;", "&");
    }
    if (import_error.length() == 0 && (artifact_name == null || artifact_name.length() == 0)) import_error = "missing_name";
    if (import_error.length() == 0 && "task".equals(artifact_type) && !artifact_name.startsWith("Hermes · Capability · ")) import_error = "invalid_task_prefix";
    if (import_error.length() == 0 && !"task".equals(artifact_type) && !artifact_name.startsWith("Hermes")) import_error = "invalid_prefix";
}

tasker.setVariable("import_xml", data_xml, true);
tasker.setVariable("import_error", import_error, true);
tasker.setVariable("import_artifact_type", artifact_type, true);
tasker.setVariable("import_name", artifact_name, true);
tasker.setVariable("import_sha256", sha256_val, true);
tasker.setVariable("import_verify_type", verify_type, true);
tasker.setVariable("import_command_id", command_id, true);
tasker.setVariable("import_result_token", result_token, true);
tasker.setVariable("import_prepare_output", "type=" + artifact_type + ";name=" + artifact_name + ";error=" + import_error, true);
return tasker.getVariable("import_prepare_output");

/* Silent Task import failed: final result. */
command_id = tasker.getVariable("import_command_id"); result_token = tasker.getVariable("import_result_token");
artifact_name = tasker.getVariable("import_name"); sha256_val = tasker.getVariable("import_sha256");
if (command_id == null) command_id = ""; if (result_token == null) result_token = ""; if (artifact_name == null) artifact_name = ""; if (sha256_val == null) sha256_val = "";
now = java.lang.System.currentTimeMillis();
result = new org.json.JSONObject(); result.put("ok", false); result.put("terminal", true); result.put("operation", "import"); result.put("state", "IMPORT_FAILED");
result.put("command_id", command_id); result.put("artifact_type", "task"); result.put("artifact_name", artifact_name); result.put("sha256", sha256_val);
result.put("error_code", "import_data_failed"); result.put("tasker_error", tasker.getVariable("err") != null ? tasker.getVariable("err") : ""); result.put("error_message", tasker.getVariable("errmsg") != null ? tasker.getVariable("errmsg") : ""); result.put("finished_at_ms", now);
result_json = result.toString();
envelope = new org.json.JSONObject(); envelope.put("schema", "hermes-tasker-result/v1"); envelope.put("operation", "import"); envelope.put("command_id", command_id); envelope.put("result_token", result_token); envelope.put("terminal", true); envelope.put("state", "IMPORT_FAILED"); envelope.put("result_json", result_json); envelope.put("finished_at_ms", now);
provider_output = "";
try { extras = new android.os.Bundle(); extras.putString("result_json", envelope.toString()); reply = context.getContentResolver().call(android.net.Uri.parse("content://com.hermesandroid.bridge.taskerresult"), "submit_result", null, extras); if (reply == null) provider_output = "accepted=false;reason=null_reply"; else { accepted = reply.getBoolean("accepted", false); reason = reply.getString("reason"); if (reason == null) reason = ""; provider_output = "accepted=" + accepted + ";reason=" + reason; } } catch (java.lang.Throwable provider_error) { provider_output = "accepted=false;reason=exception:" + provider_error.getClass().getName() + ":" + String.valueOf(provider_error.getMessage()); }
tasker.setVariable("import_result_json", result_json, true); tasker.setVariable("HermesLastImport", result_json, true); tasker.setVariable("provider_reply", provider_output); tasker.setVariable("HermesLastProviderReply", provider_output); return provider_output;

/* Silent Task import completed: final result. */
command_id = tasker.getVariable("import_command_id"); result_token = tasker.getVariable("import_result_token"); artifact_name = tasker.getVariable("import_name"); sha256_val = tasker.getVariable("import_sha256");
if (command_id == null) command_id = ""; if (result_token == null) result_token = ""; if (artifact_name == null) artifact_name = ""; if (sha256_val == null) sha256_val = "";
now = java.lang.System.currentTimeMillis();
result = new org.json.JSONObject(); result.put("ok", true); result.put("terminal", true); result.put("operation", "import"); result.put("state", "COMPLETED"); result.put("command_id", command_id); result.put("artifact_type", "task"); result.put("artifact_name", artifact_name); result.put("sha256", sha256_val); result.put("import_mode", "silent_task"); result.put("finished_at_ms", now);
result_json = result.toString(); envelope = new org.json.JSONObject(); envelope.put("schema", "hermes-tasker-result/v1"); envelope.put("operation", "import"); envelope.put("command_id", command_id); envelope.put("result_token", result_token); envelope.put("terminal", true); envelope.put("state", "COMPLETED"); envelope.put("result_json", result_json); envelope.put("finished_at_ms", now);
provider_output = "";
try { extras = new android.os.Bundle(); extras.putString("result_json", envelope.toString()); reply = context.getContentResolver().call(android.net.Uri.parse("content://com.hermesandroid.bridge.taskerresult"), "submit_result", null, extras); if (reply == null) provider_output = "accepted=false;reason=null_reply"; else { accepted = reply.getBoolean("accepted", false); reason = reply.getString("reason"); if (reason == null) reason = ""; provider_output = "accepted=" + accepted + ";reason=" + reason; } } catch (java.lang.Throwable provider_error) { provider_output = "accepted=false;reason=exception:" + provider_error.getClass().getName() + ":" + String.valueOf(provider_error.getMessage()); }
tasker.setVariable("import_result_json", result_json, true); tasker.setVariable("HermesLastImport", result_json, true); tasker.setVariable("provider_reply", provider_output); tasker.setVariable("HermesLastProviderReply", provider_output); return provider_output;

/* Stage Profile/Project privately; native Tasker Notify publishes the action button. */
command_id = tasker.getVariable("import_command_id");
result_token = tasker.getVariable("import_result_token");
data_xml = tasker.getVariable("import_xml");
artifact_type = tasker.getVariable("import_artifact_type");
artifact_name = tasker.getVariable("import_name");
sha256_val = tasker.getVariable("import_sha256");
if (command_id == null) command_id = "";
if (result_token == null) result_token = "";
if (data_xml == null) data_xml = "";
if (artifact_type == null) artifact_type = "";
if (artifact_name == null) artifact_name = "";
if (sha256_val == null) sha256_val = "";

now = java.lang.System.currentTimeMillis();
stage_error = "";
pending_key = "";
notification_title = "";
try {
    key_material = command_id + "\n" + sha256_val;
    key_digest = java.security.MessageDigest.getInstance("SHA-256").digest(key_material.getBytes("UTF-8"));
    key_hex = "";
    for (key_index = 0; key_index < key_digest.length; key_index++) {
        key_part = java.lang.Integer.toHexString(key_digest[key_index] & 255);
        if (key_part.length() < 2) key_hex += "0";
        key_hex += key_part;
    }
    pending_key = key_hex.substring(0, 32);
    notification_title = "Hermes · Import · " + pending_key;

    pending_dir = new java.io.File(context.getFilesDir(), "hermes_pending_imports_v2_4");
    if (!pending_dir.exists() && !pending_dir.mkdirs()) throw new java.io.IOException("cannot_create_pending_dir");
    xml_file = new java.io.File(pending_dir, pending_key + ".xml");
    meta_file = new java.io.File(pending_dir, pending_key + ".json");
    xml_tmp = new java.io.File(pending_dir, pending_key + ".xml.tmp");
    meta_tmp = new java.io.File(pending_dir, pending_key + ".json.tmp");

    xml_out = new java.io.FileOutputStream(xml_tmp, false);
    xml_out.write(data_xml.getBytes("UTF-8"));
    xml_out.flush();
    xml_out.getFD().sync();
    xml_out.close();

    meta = new org.json.JSONObject();
    meta.put("schema", "hermes-pending-import/v2");
    meta.put("pending_key", pending_key);
    meta.put("command_id", command_id);
    meta.put("result_token", result_token);
    meta.put("artifact_type", artifact_type);
    meta.put("artifact_name", artifact_name);
    meta.put("sha256", sha256_val);
    meta.put("notification_title", notification_title);
    meta.put("created_at_ms", now);

    meta_out = new java.io.FileOutputStream(meta_tmp, false);
    meta_out.write(meta.toString().getBytes("UTF-8"));
    meta_out.flush();
    meta_out.getFD().sync();
    meta_out.close();

    if (xml_file.exists() && !xml_file.delete()) throw new java.io.IOException("cannot_replace_xml");
    if (meta_file.exists() && !meta_file.delete()) throw new java.io.IOException("cannot_replace_meta");
    if (!xml_tmp.renameTo(xml_file)) throw new java.io.IOException("cannot_commit_xml");
    if (!meta_tmp.renameTo(meta_file)) throw new java.io.IOException("cannot_commit_meta");
} catch (java.lang.Throwable stage_exception) {
    stage_error = "stage_failed:" + stage_exception.getClass().getName() + ":" + String.valueOf(stage_exception.getMessage());
}

