/* Load and lock one staged Profile/Project selected by a native Notify action. */
pending_key = tasker.getVariable("par1");
if (pending_key == null) pending_key = "";
command_id = "";
result_token = "";
confirm_error = "";
data_xml = "";
artifact_type = "";
artifact_name = "";
sha256_val = "";
notification_title = "";
lock_acquired = false;
try {
    if (!pending_key.matches("[0-9a-f]{32}")) throw new java.lang.IllegalArgumentException("invalid_pending_key");
    pending_dir = new java.io.File(context.getFilesDir(), "hermes_pending_imports_v2_4");
    xml_file = new java.io.File(pending_dir, pending_key + ".xml");
    meta_file = new java.io.File(pending_dir, pending_key + ".json");
    lock_file = new java.io.File(pending_dir, pending_key + ".lock");
    if (!xml_file.isFile() || !meta_file.isFile()) throw new java.io.FileNotFoundException("pending_not_found");

    meta_bytes = java.nio.file.Files.readAllBytes(meta_file.toPath());
    meta = new org.json.JSONObject(new java.lang.String(meta_bytes, "UTF-8"));
    if (!pending_key.equals(meta.optString("pending_key", ""))) throw new java.lang.SecurityException("pending_key_mismatch");
    command_id = meta.optString("command_id", "");
    result_token = meta.optString("result_token", "");
    artifact_type = meta.optString("artifact_type", "");
    artifact_name = meta.optString("artifact_name", "");
    sha256_val = meta.optString("sha256", "");
    notification_title = meta.optString("notification_title", "Hermes · Import · " + pending_key);
    if (command_id.length() == 0) throw new java.lang.SecurityException("missing_command_id");
    if (result_token.length() == 0) throw new java.lang.SecurityException("missing_result_token");
    if (!"profile".equals(artifact_type) && !"project".equals(artifact_type)) throw new java.lang.SecurityException("unsupported_deferred_type");

    data_bytes = java.nio.file.Files.readAllBytes(xml_file.toPath());
    data_xml = new java.lang.String(data_bytes, "UTF-8");
    digest_bytes = java.security.MessageDigest.getInstance("SHA-256").digest(data_bytes);
    hex_buf = "";
    for (digest_index = 0; digest_index < digest_bytes.length; digest_index++) {
        hex_part = java.lang.Integer.toHexString(digest_bytes[digest_index] & 255);
        if (hex_part.length() < 2) hex_buf += "0";
        hex_buf += hex_part;
    }
    if (!sha256_val.equals(hex_buf)) throw new java.lang.SecurityException("sha256_mismatch");

    lock_acquired = lock_file.createNewFile();
    if (!lock_acquired) throw new java.lang.IllegalStateException("import_in_progress");
} catch (java.lang.Throwable confirm_exception) {
    confirm_error = confirm_exception.getMessage();
